public interface IElevatorScheduler
{
    Elevator Assign(Request request, IReadOnlyList<Elevator> elevators);
}

public class LookScheduler : IElevatorScheduler
{
    public Elevator Assign(Request request, IReadOnlyList<Elevator> elevators)
    {
        // Prefer elevator already moving in the same direction
        var sameDirection = elevators.Where(e =>
            e.Direction == request.Direction &&
            Math.Abs(e.CurrentFloor - request.Floor) <= 5).ToList();

        if (sameDirection.Count > 0)
            return sameDirection.MinBy(e => Math.Abs(e.CurrentFloor - request.Floor))!;

        // Otherwise pick the idle elevator closest to the request
        var idle = elevators.Where(e => e.Direction == Direction.Idle).ToList();
        if (idle.Count > 0)
            return idle.MinBy(e => Math.Abs(e.CurrentFloor - request.Floor))!;

        // Fallback: elevator with lightest queue
        return elevators.MinBy(e => e.QueueDepth)!;
    }
}
